        if stream_opt.is_none() { ret false }
        stream := stream_opt.unwrap()
        ok := stream.write_str(content)
        stream.close()
        ok
    }

    exists :: fn(path Str) bool {
        stream_opt := File.open_read(path)
        if stream_opt.is_some() {
            stream := stream_opt.unwrap()
            stream.close()
            ret true
        }
        false
    }

    size :: fn(path Str) u64 {
        stream_opt := File.open_read(path)
        if stream_opt.is_some() {
            stream := stream_opt.unwrap()
            s := stream.size()
            stream.close()
            ret s
        }
        0
    }
}

read_file :: fn(a &Arena, path &u8) Str {
    source := try_read_file(a, path)
    if source.ptr == (0 as &u8) {
        print_cstr(c"\n\033[1;31merror:\033[0m cannot open file '")
        print_cstr(path)
        print_cstr(c"': file not found or permission denied\n")
        fall()
    }
    source
}

try_read_file :: fn(a &Arena, path &u8) Str {
    opt := File.read_to_string(a, Str.of(path))
    if opt.is_some() { ret opt.unwrap() }
    Str.empty()
}

write_file :: fn(path &u8, content Str) bool {
    ok := File.write_string(Str.of(path), content)
    if not ok {
        print_cstr(c"\n\033[1;31merror:\033[0m failed to write file '")
        print_cstr(path)
        print_cstr(c"'\n")
        fall()
    }
    true
}

append_file :: fn(path &u8, content Str) bool {
    ok := File.append_string(Str.of(path), content)
    if not ok {
        print_cstr(c"\n\033[1;31merror:\033[0m failed to append to file '")
